import { agentResponse } from "./lib/agent-content/negotiation";
import { syncJobBoard } from "./lib/job-board/sync";
// @ts-ignore Generated by `opennextjs-cloudflare build` before Wrangler runs.
import handler from "./.open-next/worker.js";

interface ScheduledEnv extends CloudflareEnv {
  CRON_SECRET: string;
  NEXT_PUBLIC_APP_URL?: string;
}

interface ScheduledEventLike {
  cron: string;
}

interface ExecutionContextLike {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

const CRON_ROUTES: Record<string, string> = {
  "0 3 * * *": "/api/cron/cleanup-views",
};

export default {
  async fetch(request: Request, env: ScheduledEnv, ctx: ExecutionContextLike): Promise<Response> {
    const response = await handler.fetch(request, env, ctx);
    // Creator portfolio hosts keep their own content and representation policy.
    const hostname = new URL(request.url).hostname;
    if (!["ugc.community", "www.ugc.community", "localhost", "127.0.0.1"].includes(hostname) && !hostname.endsWith(".workers.dev")) return response;
    return agentResponse(request, response);
  },

  async scheduled(
    event: ScheduledEventLike,
    env: ScheduledEnv,
    ctx: ExecutionContextLike
  ): Promise<void> {
    if (event.cron === "*/10 * * * *") {
      await syncJobBoard(env);
      return;
    }

    const path = CRON_ROUTES[event.cron];
    if (!path) {
      console.warn(`No route configured for cron expression: ${event.cron}`);
      return;
    }

    if (!env.CRON_SECRET) {
      throw new Error("CRON_SECRET is required for scheduled jobs");
    }

    const baseUrl = env.NEXT_PUBLIC_APP_URL || "https://ugc.community";
    const response = await handler.fetch(
      new Request(new URL(path, baseUrl), {
        headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
      }),
      env,
      ctx
    );

    if (!response.ok) {
      throw new Error(`${path} failed with ${response.status}`);
    }

    console.log(`${path} completed with ${response.status}`);
  },
};
